import{o as t,c as i,a as e}from"./app.fcda16e3.js";const p='{"title":"git忽略文件上传 笔记","description":"","frontmatter":{},"headers":[{"level":2,"title":"git忽略文件上传 笔记","slug":"git忽略文件上传-笔记"}],"relativePath":"other/wz2.md","lastUpdated":1689665502079}',a={},s=e('<div class="tip custom-block"><p class="custom-block-title">文献</p><p>笔记 果汁 🍹</p></div><h2 id="git忽略文件上传-笔记"><a class="header-anchor" href="#git忽略文件上传-笔记" aria-hidden="true">#</a> git忽略文件上传 笔记</h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>1、 首先在你git所管理文件夹根目录下,创建一个名为 .gitignore 的文件, 注意 这种方式对已经提交到git上面的文件是无法奏效的,例如在.gitignore这个文件存在前,</p><p>.project这个文件已经托管提交给git了,</p><p>那后面在.gitignore这个文件里添加.project表示忽略这个文件也不行,</p><p>git依然会帮我们提交这时候需要用到第二种方法。</p><p>2、 忽略某个已经托管给git的文件,防止二次提交 这种情况适用于,每个人修改了项目的配置,但是这个是临时的,只适用于自己本地的情况,不可提交给大家公用时,需要这么做。 复制代码</p><p>执行命令将文件加入不提交队列 git update-index --assume-unchanged 你的文件路径</p><p>执行命令将文件取消加入不提交队列 git update-index --no-assume-unchanged 你的文件路径</p></div>',3);a.render=function(e,p,a,o,r,c){return t(),i("div",null,[s])};export default a;export{p as __pageData};
